fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    // Compute ceil(health / strength) = (health + strength - 1) / strength
    let h = health as i64;
    let s = strength as i64;
    (h + s - 1) / s
}

fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    // a: Takahashi's health
    // b: Takahashi's attack
    // c: Aoki's health
    // d: Aoki's attack

    // Number of turns for Takahashi to defeat Aoki:
    let takahashi_turns = exec_turns_to_defeat(c, b);
    // Number of turns for Aoki to defeat Takahashi:
    let aoki_turns = exec_turns_to_defeat(a, d);

    if takahashi_turns <= aoki_turns {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}